// === Tab: mySketch ===
let particles = [];
let magnet;

function setup() {
  createCanvas(windowWidth, windowHeight);

  for(let i = 0;i<100;i++){
    particles.push({
      x:random(width),
      y:random(height),
      vx:0,
      vy:0
    });
  }
  magnet = createVector(width/2, height/2);
  colorMode(HSB, 360, 100, 255, 255);

}

function draw() {
  background(20);
  let target = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  magnet.lerp(target, 0.1);


  for(let p of particles){
    let dx = magnet.x - p.x;
    let dy = magnet.y - p.y;
    let distSq = dx*dx + dy * dy;
    let distSqrt = sqrt(distSq);

    if(distSqrt < 10){
      p.vx *= 0.5;
      p.vy *= 0.5;
      continue;
    }

    let force = 1000/distSq; // inverse square law
    //unit vector force
    let fx = (dx / distSqrt) * force;
    let fy = (dy/distSqrt) * force;

    //apply force
    p.vx += fx;
    p.vy += fy;

    //damping
    p.vx *= 0.97;
    p.vy *= 0.97;

    p.x += p.vx;
    p.y += p.vy;


    //wrap around screen
    if(p.x < -50) p.x = width + 50;
    if(p.x > width + 50) p.x = -50;
    if(p.y < -50) p.y = height + 50;
    if(p.y > height + 50) p.y = -50;

    if (distSqrt < 150) { // adjust threshold as needed
      let glowAlpha = map(distSqrt, 0, 150, 100, 0); 
      let glowHue = map(distSqrt, 0, 150, 180, 220); 
      fill(glowHue, 80, 255, glowAlpha);
      noStroke();
      ellipse(p.x, p.y, 60); 
    }


    let saturation = map(distSqrt, 0, width, 80, 30);      // 100 near magnet → 0 far
    let brightness = map(distSqrt, 0, width, 240, 100);
    let alpha = map(distSqrt, 0, width, 255, 80);
    noStroke();
    fill(180, saturation, brightness, alpha);
    ellipse(p.x, p.y, 30);
  }
  push();
  translate(magnet.x, magnet.y);

  let pulse = sin(frameCount *0.1) * 5+ 30;
  let hue = map(sin(frameCount * 0.01), -1, 1, 280, 330); 

  noFill();
  stroke(hue, 100, 255, 100);
  strokeWeight(12);
  ellipse(0, 0, pulse + 50);


  //orbiting sparks
  let sparkCount = 6;
  strokeWeight(4);
  for(let i = 0;i<sparkCount;i++){
    let sparkR = 20 + sin(frameCount * 0.2 + i)* 5;
    var alpha = map(sin(frameCount * 0.1 + i), -1, 1, 50, 180);
    let angle = frameCount * 0.05 + i * TWO_PI / sparkCount;
    let x = cos(angle)* sparkR;
    let y = sin(angle) * sparkR;
    stroke((hue), 100, 255, alpha);
    point(x, y);
  }

  noStroke();
  fill(hue, 100, 255);
  ellipse(0, 0, pulse);
  pop();
}

